// Client Credentials Flow example using Spring Security OAuth2 Client
WebClient webClient = WebClient.builder()
    .filter(new ServletOAuth2AuthorizedClientExchangeFilterFunction(clientRegistrationRepository, authorizedClientRepository))
    .build();

// The filter automatically handles the token request and injection into the Authorization header
String response = webClient.get()
    .uri("https://api.example.com/data")
    .attributes(clientRegistrationId("my-service-client"))
    .retrieve()
    .bodyToMono(String.class)
    .block();
